import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static boolean hasNext() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
        return pos < buf.length;
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        nextLong();
        // arr[i] = pref[i-1] ^ pref[i]; the shared prefix cancels out.
        long previous = 0;
        StringBuilder sb = new StringBuilder();
        while (hasNext()) {
            long value = nextLong();
            if (sb.length() > 0) sb.append(' ');
            sb.append(previous ^ value);
            previous = value;
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	sc.Scan()
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	// arr[i] = pref[i-1] ^ pref[i]; the shared prefix cancels out.
	var previous int64
	first := true
	for sc.Scan() {
		value, _ := strconv.ParseInt(sc.Text(), 10, 64)
		if !first {
			w.WriteByte(' ')
		}
		first = false
		w.WriteString(strconv.FormatInt(previous^value, 10))
		previous = value
	}
	w.WriteByte('\n')
}
